suppressPackageStartupMessages({library(ggplot2);library(dplyr);library(readr);library(patchwork)})
o<-normalizePath('8-Visualization/refinements/fig3_focused_revision_20261103_v3/supplement');f<-file.path(o,'figures');s<-file.path(o,'source_data')
a<-'8-Visualization/refinements/fig3_scientific_enhancement_20261103_v2/source_data';c<-'7-SingleCell/runs/20261103_figure3_cnv_program_cases_v1/tables'
for(n in c('method_concordance.csv','identity_sensitivity_contrasts.csv','patient_associations.csv'))file.copy(file.path(a,n),file.path(s,n),overwrite=TRUE)
for(n in c('program_distribution_summary.csv','program_support_coverage.csv','cell_support.csv','original_patient_CNV_support.csv','program_distributions.csv.gz'))file.copy(file.path(c,n),file.path(s,n),overwrite=TRUE)
base<-theme_classic(base_family='Arial',base_size=6)+theme(plot.title=element_text(size=7,face='bold'),plot.subtitle=element_text(size=5.5,colour='#555555'),plot.caption=element_text(size=5,hjust=0),axis.title=element_text(size=5.5),axis.text=element_text(size=5.3,colour='#333333'),legend.title=element_text(size=5.3),legend.text=element_text(size=5.3),legend.position='bottom',strip.text=element_text(size=5.7,face='bold'),strip.background=element_rect(fill='#F0F2F3',colour=NA),panel.spacing=grid::unit(2,'mm'),plot.margin=margin(2,2,2,2))
theme_set(base)
savefig<-function(p,name,h){svglite::svglite(file.path(f,paste0(name,'.svg')),width=174/25.4,height=h/25.4);print(p);dev.off();cairo_pdf(file.path(f,paste0(name,'.pdf')),width=174/25.4,height=h/25.4,family='Arial');print(p);dev.off();ragg::agg_png(file.path(f,paste0(name,'.png')),width=174,height=h,units='mm',res=600);print(p);dev.off()}
# All eligible tumor contrasts for each fixed scoring alternative.
m<-read_csv(file.path(s,'method_concordance.csv'),show_col_types=FALSE)%>%filter(tissue=='Tumor',NPatients_UCell>=4,NPatients_other>=4)
ms<-m%>%group_by(Comparator)%>%summarise(N=n(),Agree=sum(SameDirection),Disagree=sum(!SameDirection),.groups='drop')
stopifnot(nrow(ms)==5,all(ms$N==49),sum(ms$Disagree)==10)
mlab<-c(NativeRank='Native rank',LogControl='Log-control',UCell1000='UCell maxRank 1000',UCell3000='UCell maxRank 3000',UCellCommon='Common members')
ms$Method<-factor(mlab[ms$Comparator],levels=rev(unname(mlab)));ms$txt<-sprintf('%d / 49; %d differ',ms$Agree,ms$Disagree)
p1<-ggplot(ms,aes(y=Method))+geom_segment(aes(x=0,xend=49,yend=Method),linewidth=2.2,colour='#D6D9DC')+geom_segment(aes(x=0,xend=Agree,yend=Method),linewidth=2.2,colour='#3F7381')+geom_text(aes(x=50,label=txt),hjust=0,size=5.3/.pt)+scale_x_continuous(limits=c(0,75),breaks=c(0,25,49))+labs(title='Scoring alternatives',subtitle='Direction versus UCell; all 49 matched tumor contrasts',x='Concordant contrasts',y=NULL)
id<-read_csv(file.path(s,'identity_sensitivity_contrasts.csv'),show_col_types=FALSE)%>%filter(Status=='qualified_tumor_n4')
stopifnot(nrow(id)==49,all(id$SameDirection),all(id$NMatchedSameEligibleLibraries==id$NMatched))
id$cohort<-factor(id$cohort,levels=c('GSE151530','GSE138709'))
lims<-range(c(id$BroadEffect,id$CleanEffect));lims<-lims+c(-.006,.006)
p2<-ggplot(id,aes(BroadEffect,CleanEffect))+geom_abline(slope=1,intercept=0,linetype='dashed',colour='#999999',linewidth=.3)+geom_point(aes(shape=cohort),colour='#3F7381',size=1.2,stroke=.3)+scale_shape_manual(values=c(16,17),labels=c('GSE151530','GSE138709'),name=NULL)+coord_fixed(xlim=lims,ylim=lims)+labs(title='Broad versus clean eligibility',subtitle='49 / 49 retained; circle: GSE151530, triangle: GSE138709',x='Broad effect',y='Clean effect')+theme(legend.position='none')
p3<-(p1+p2)+plot_layout(widths=c(1.22,1))+plot_annotation(caption=sprintf('Broad–clean |effect change|: median %.5f, maximum %.5f UCell units. Full contrasts and unsupported combinations remain in Source Data.',median(abs(id$EffectChange)),max(abs(id$EffectChange))),theme=theme(plot.caption=element_text(family='Arial',size=5,hjust=0),plot.margin=margin(0,0,0,0)))
savefig(p3,'S4_robustness',53)
write_csv(ms,file.path(s,'plot_scoring_summary.csv'));write_csv(id,file.path(s,'plot_identity_matched.csv'))
# All six fixed associations; endpoints are LOO estimates, not CI.
tm<-read_csv(file.path(s,'patient_associations.csv'),show_col_types=FALSE)%>%filter(Method=='UCell')
stopifnot(nrow(tm)==6,all(tm$FDR>=.05))
tl<-c(C1_metabolic_IFN='Epithelial P2 — myeloid IFN',C2_epithelial_IFN='Epithelial P3 — myeloid IFN',C3_epithelial_IFN='Epithelial P4 — myeloid IFN',C3_epithelial_Tcycle='Epithelial P4 — T/NK cycle',C3_epithelial_fibroblast='Epithelial P4 — fibroblast fraction',C2_epithelial_myeloid='Epithelial P3 — myeloid fraction')
tm$Label<-factor(tl[tm$Association],levels=rev(unname(tl)));tm$txt<-sprintf('n = %d; q = %.3f',tm$NPatients,tm$FDR)
p<-ggplot(tm,aes(y=Label))+geom_vline(xintercept=0,linewidth=.3,linetype='dashed',colour='#999999')+geom_segment(aes(x=LOOMin,xend=LOOMax,yend=Label),linewidth=.7,colour='#9EAFB7')+geom_point(aes(x=AdjustedR),size=1.6,colour='#284E60')+geom_text(aes(x=1.05,label=txt),hjust=0,size=5.5/.pt)+scale_x_continuous(limits=c(-1,1.8),breaks=c(-1,-.5,0,.5,1))+labs(title='All six prespecified epithelial–TME associations',subtitle='Point: cohort-adjusted rank correlation. Bar: leave-one-patient range, not a confidence interval.',x='Adjusted correlation',y=NULL,caption='8–12 independent patients; within-cohort permutation tests and BH correction across all six comparisons. None reaches q < 0.05.')
savefig(p,'S4_TME_associations',49);write_csv(tm,file.path(s,'plot_TME_associations.csv'))
# All six programs; complete four patient/region contexts. Other epithelium is not normal.
cn<-read_csv(file.path(s,'program_distribution_summary.csv'),show_col_types=FALSE)
cv<-read_csv(file.path(s,'program_support_coverage.csv'),show_col_types=FALSE)
pr<-c('Pattern_P2','Pattern_P3','WGCNA_MEcyan','Pattern_P4','WGCNA_MEmagenta','WGCNA_MEdarkturquoise')
pl<-c('P2','P3','cyan · Respiration','P4','magenta · Mitotic cycle','darkturquoise · IFN');names(pl)<-pr
cases<-c('ICC_20_Tumor','ICC_18_Tumor','ICC_24_Tumor1','ICC_24_Tumor2')
cl<-c('ICC20  27 / 2,017','ICC18  6 / 4,320','ICC24 T1  9 / 1,803','ICC24 T2  0 / 118');names(cl)<-cases
cn<-cn%>%filter(ProgramID%in%pr,Sample%in%cases);stopifnot(nrow(cn)==40)
cn$Program<-factor(pl[cn$ProgramID],levels=pl);cn$Case<-factor(cl[cn$Sample],levels=rev(cl));cn$Group<-factor(ifelse(cn$StrictCandidate,'Strict candidate','Other epithelium'),levels=c('Other epithelium','Strict candidate'));cn$yy<-as.numeric(cn$Case)+ifelse(cn$StrictCandidate,.13,-.13)
missing<-expand.grid(ProgramID=pr,Sample=cases,stringsAsFactors=FALSE);missing$Program<-factor(pl[missing$ProgramID],levels=pl);missing$Case<-factor(cl[missing$Sample],levels=rev(cl));missing$yy<-as.numeric(missing$Case)
missing<-missing%>%filter((Sample=='ICC_18_Tumor'&ProgramID=='Pattern_P2')|Sample=='ICC_24_Tumor2')
missing$txt<-ifelse(missing$Sample=='ICC_18_Tumor','coverage <70%','0 candidates');missing$yy<-ifelse(missing$Sample=='ICC_24_Tumor2',missing$yy+.14,missing$yy)
# Use one common score axis throughout; compare candidate/other within a program, not across program magnitudes.
p<-ggplot(cn,aes(y=yy,colour=Group,shape=Group))+geom_segment(aes(x=Q25,xend=Q75,yend=yy),linewidth=.5)+geom_point(aes(x=Median),size=1.1,stroke=.35)+geom_text(data=missing,aes(x=.29,y=yy,label=txt),inherit.aes=FALSE,hjust=1,size=5/.pt,colour='#666666')+facet_wrap(~Program,ncol=3,drop=FALSE)+scale_y_continuous(breaks=1:4,labels=rev(cl),limits=c(.5,4.5))+scale_x_continuous(limits=c(0,.30),breaks=c(0,.1,.2,.3))+scale_colour_manual(values=c('Other epithelium'='#6D8594','Strict candidate'='#B77E4E'),name=NULL)+scale_shape_manual(values=c('Other epithelium'=1,'Strict candidate'=16),name=NULL)+labs(title='Qualified CNV cases: program distributions',subtitle='Row labels: strict candidates / clean tumor epithelial cells. Points and bars: cell median and IQR.',x='UCell score',y=NULL,caption='Three patients; ICC24 regions are not independent. Candidate status is descriptive; other epithelium is not labelled normal. No cell-level tests.')+theme(axis.text.y=element_text(size=5),legend.margin=margin(0,0,0,0),legend.key.height=grid::unit(2,'mm'),legend.box.margin=margin(0,0,0,0),plot.caption=element_text(size=5))
savefig(p,'S4_CNV_cases',65);write_csv(cn,file.path(s,'plot_CNV_summary.csv'));write_csv(missing,file.path(s,'plot_CNV_missing.csv'))
write_csv(data.frame(Panel=c('S4_robustness','S4_TME_associations','S4_CNV_cases'),Width_mm=174,Height_mm=c(53,49,65),DPI=600),file.path(s,'export_dimensions.csv'))
writeLines(c('49 contrasts per scoring alternative; agree/disagree all retained.','Broad/Clean 49 matched contrasts; 49 same direction; no tests recomputed.','All six UCell TME associations, n/FDR and LOO endpoints preserved.','CNV 40 estimable program/status summaries; six program panels; all four case/region contexts; six zero-candidate annotations and one low-coverage annotation.'),file.path(o,'review/verification.txt'))
